// ─────────── среда выполнения bit (x86_64) ───────────
// аргументы: rdi, rsi, rdx, rcx, r8, r9; результат: rax
.p2align 4
_bit_recover_enter:                 // rdi = frame allocated by the compiler
    mov rax, [rip + Lrt_recover]
    mov [rdi + 168], rax
    mov [rip + Lrt_recover], rdi
    mov rax, [rip + Lrt_owned]
    mov [rdi + 176], rax
    mov rax, rdi
    ret

_bit_recover_leave:
    mov rax, [rip + Lrt_recover]
    mov rax, [rax + 168]
    mov [rip + Lrt_recover], rax
    ret

_bit_own_str:                       // rdi = stack record with string and previous pointer
    mov rax, [rip + Lrt_owned]
    mov [rdi + 8], rax
    mov [rip + Lrt_owned], rdi
    ret

_bit_drop_owned:
    mov rax, [rip + Lrt_owned]
    mov rcx, [rax + 8]
    mov [rip + Lrt_owned], rcx
    mov rdi, [rax]
    jmp _bit_drop_str

_bit_setjmp:                        // rdi = буфер → 0; сохраняет callee-saved, sp и адрес возврата
    mov [rdi], rbx
    mov [rdi + 8], rbp
    mov [rdi + 16], r12
    mov [rdi + 24], r13
    mov [rdi + 32], r14
    mov [rdi + 40], r15
    lea rdx, [rsp + 8]
    mov [rdi + 48], rdx
    mov rdx, [rsp]
    mov [rdi + 56], rdx
    xor eax, eax
    ret

_bit_longjmp:                       // rdi = буфер, rsi = значение → возврат из _bit_setjmp
    mov rbx, [rdi]
    mov rbp, [rdi + 8]
    mov r12, [rdi + 16]
    mov r13, [rdi + 24]
    mov r14, [rdi + 32]
    mov r15, [rdi + 40]
    mov rsp, [rdi + 48]
    mov rax, rsi
    jmp qword ptr [rdi + 56]

_bit_term_error:                    // → копия текста последней пойманной ошибки ("" если не было)
    push rbp
    mov rbp, rsp
    push rbx
    push r12
    mov rbx, [rip + Lrt_errmsg]
    test rbx, rbx
    jnz 1f
    mov edi, 1
    call _bit_alloc
    mov byte ptr [rax], 0
    jmp 2f
1:  mov rdi, rbx
    call strlen@PLT
    mov rsi, rax
    mov rdi, rbx
    call _bit_substr
2:  pop r12
    pop rbx
    pop rbp
    ret

_bit_die:                           // rdi = сообщение, rsi = строка программы
    mov rax, [rip + Lrt_recover]
    test rax, rax
    jz 5f
    mov [rip + Lrt_errmsg], rdi
    mov [rip + Lrt_errline], rsi
    mov rcx, [rax + 168]
    mov [rip + Lrt_recover], rcx
    push rax
1:  mov rcx, [rip + Lrt_owned]
    cmp rcx, [rax + 176]
    je 2f
    call _bit_drop_owned
    mov rax, [rsp]
    jmp 1b
2:  pop rdi
    mov esi, 1
    jmp _bit_longjmp
